import React from 'react';
import { SECTORS, RECENTLY_USED_SCREENS, MOST_USED_SCREENS, ALL_SCREENS } from '../constants';
import ToggleSwitch from './ToggleSwitch';
import { MenuAlt2Icon } from './Icons';
import { Screen } from '../types';

interface SidebarProps {
  selectedSectors: string[];
  onSelectSector: (sector: string) => void;
  sectorSearch: string;
  onSectorSearchChange: (value: string) => void;
  nseOnly: boolean;
  setNseOnly: (enabled: boolean) => void;
  onRunScreen: (screen: Screen) => void;
}

const Sidebar: React.FC<SidebarProps> = ({ 
  selectedSectors, 
  onSelectSector, 
  sectorSearch, 
  onSectorSearchChange, 
  nseOnly, 
  setNseOnly,
  onRunScreen
}) => {
  const filteredSectors = SECTORS.filter(s => 
    s.toLowerCase().includes(sectorSearch.toLowerCase())
  );

  const handleRunScreenByName = (screenName: string) => {
    const screenToRun = ALL_SCREENS.find(s => s.title === screenName);
    if (screenToRun) {
      onRunScreen(screenToRun);
    } else {
      console.warn(`Screen "${screenName}" not found.`);
    }
  };

  return (
    <aside className="col-span-3">
      <div className="sticky top-20 max-h-[calc(100vh-6.5rem)] overflow-y-auto space-y-6 pr-2">
        <div className="bg-brand-container border border-brand-border rounded-xl p-4">
          <div className="flex justify-between items-center mb-4">
            <h2 className="font-semibold text-brand-text-primary">Filter by Sector</h2>
            <span className="text-xs font-medium text-brand-primary bg-brand-primary/20 px-2 py-1 rounded-full">Quick Filter</span>
          </div>

          <div className="relative mb-4">
            <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
              <MenuAlt2Icon className="h-5 w-5 text-brand-text-tertiary" />
            </div>
            <input
              type="text"
              placeholder="Search sector..."
              value={sectorSearch}
              onChange={(e) => onSectorSearchChange(e.target.value)}
              className="block w-full bg-brand-bg border border-brand-border rounded-lg py-2 pl-10 pr-3 text-sm placeholder-brand-text-tertiary focus:outline-none focus:ring-1 focus:ring-brand-primary focus:border-brand-primary"
            />
          </div>

          <nav className="flex flex-col space-y-1">
            {filteredSectors.map(sector => {
              const isSelected = selectedSectors.includes(sector);
              return (
                <button
                  key={sector}
                  onClick={() => onSelectSector(sector)}
                  className={`w-full text-left px-3 py-1.5 rounded-md text-sm transition-colors flex items-center gap-3 ${
                    isSelected
                    ? 'bg-brand-primary/10 text-brand-primary' 
                    : 'text-brand-text-secondary hover:bg-white/5 hover:text-brand-text-primary'
                  }`}
                >
                  <span className={`w-1.5 h-1.5 rounded-full ${isSelected ? 'bg-brand-primary' : 'bg-brand-text-tertiary'}`}></span>
                  {sector}
                </button>
              );
            })}
          </nav>
          
          <ToggleSwitch label="Include only NSE" enabled={nseOnly} setEnabled={setNseOnly} />
        </div>
        
        <div className="bg-brand-container border border-brand-border rounded-xl p-4">
            <h4 className="font-semibold text-brand-text-primary mb-3">Recently Used</h4>
            <div className="flex flex-wrap gap-2">
                {RECENTLY_USED_SCREENS.map(name => (
                    <button 
                      key={name} 
                      onClick={() => handleRunScreenByName(name)}
                      className="px-3 py-1 text-xs font-medium rounded-md bg-neutral-800 hover:bg-neutral-700 text-brand-text-secondary transition-colors"
                    >
                        {name}
                    </button>
                ))}
            </div>
        </div>

        <div className="bg-brand-container border border-brand-border rounded-xl p-4">
            <h4 className="font-semibold text-brand-text-primary mb-3">Most Used</h4>
            <div className="flex flex-wrap gap-2">
                {MOST_USED_SCREENS.map(name => (
                    <button 
                      key={name}
                      onClick={() => handleRunScreenByName(name)}
                      className="px-3 py-1 text-xs font-medium rounded-md bg-neutral-800 hover:bg-neutral-700 text-brand-text-secondary transition-colors"
                    >
                        {name}
                    </button>
                ))}
            </div>
        </div>
      </div>
    </aside>
  );
};

export default Sidebar;