import React, { useState, useEffect } from 'react';
import { Screen, Stock } from '../types';
import { ArrowLeftIcon } from './Icons';
import { getStocksForCombination } from '../data';
import ScreenCombiner from './ScreenCombiner';

interface ScreenResultsProps {
  initialScreens: Screen[];
  onClose: () => void;
  selectedSectors: string[];
  onSaveCombination: (screens: Screen[]) => void;
}

const ScreenResults: React.FC<ScreenResultsProps> = ({ initialScreens, onClose, selectedSectors, onSaveCombination }) => {
  const [currentScreens, setCurrentScreens] = useState<Screen[]>(initialScreens);
  const [allStocks, setAllStocks] = useState<Stock[]>([]);

  useEffect(() => {
    // This calculates the intersection of stocks from all current screens
    setAllStocks(getStocksForCombination(currentScreens));
  }, [currentScreens]);

  const filteredStocks = selectedSectors.includes('All')
    ? allStocks
    : allStocks.filter(stock => selectedSectors.includes(stock.sector));
    
  const getSectorDisplayText = () => {
    if (selectedSectors.includes('All') || selectedSectors.length === 0) {
      return '';
    }
    const prefix = selectedSectors.length === 1 ? ' for sector: ' : ' for sectors: ';
    return (
      <>
        {prefix}
        <span className="text-brand-text-secondary font-sans font-medium">{selectedSectors.join(', ')}</span>
      </>
    );
  };

  const handleAddScreen = (screenToAdd: Screen) => {
    if (!currentScreens.some(s => s.title === screenToAdd.title)) {
      setCurrentScreens([...currentScreens, screenToAdd]);
    }
  };

  const handleRemoveScreen = (screenTitleToRemove: string) => {
    if (currentScreens.length > 1) {
      setCurrentScreens(currentScreens.filter(s => s.title !== screenTitleToRemove));
    }
  };
  
  const mainTitle = currentScreens.length === 1 
    ? currentScreens[0].title 
    : "Combined Screen";
    
  const mainDescription = currentScreens.length === 1 
    ? currentScreens[0].description
    : `Intersection of ${currentScreens.length} screens, showing stocks that match all criteria.`;

  return (
    <div className="col-span-9 bg-brand-container border border-brand-border rounded-xl">
      <div className="p-4 border-b border-brand-border space-y-4">
        <div>
          <button onClick={onClose} className="flex items-center gap-2 text-sm text-brand-text-secondary hover:text-brand-text-primary transition-colors mb-2">
            <ArrowLeftIcon className="w-4 h-4" />
            Back to Dashboard
          </button>
          <h2 className="text-xl font-bold text-brand-text-primary">{mainTitle}</h2>
          <p className="text-sm text-brand-text-secondary">{mainDescription}</p>
        </div>
        
        <div>
            <p className="text-xs text-brand-text-tertiary mb-2">Active Screens:</p>
            <div className="flex flex-wrap items-center gap-2">
              {currentScreens.map(s => (
                <div key={s.title} className="flex items-center gap-1 bg-brand-primary/10 text-brand-primary text-xs font-medium rounded-full pl-3 pr-2 py-1">
                  <span>{s.title}</span>
                  {currentScreens.length > 1 && (
                    <button onClick={() => handleRemoveScreen(s.title)} className="w-4 h-4 rounded-full hover:bg-white/20 flex items-center justify-center">&times;</button>
                  )}
                </div>
              ))}
            </div>
        </div>

        <div className="flex items-center justify-between flex-wrap gap-2">
          <ScreenCombiner 
            currentScreens={currentScreens}
            onAddScreen={handleAddScreen}
          />
          {currentScreens.length > 1 && (
             <button
                onClick={() => onSaveCombination(currentScreens)}
                className="px-4 py-1.5 text-sm font-medium rounded-lg bg-brand-primary text-black hover:bg-opacity-80 transition-colors"
              >
                Save this Combination
              </button>
          )}
        </div>
      </div>
      
      <div className="p-2 border-b border-brand-border">
          <p className="text-xs text-brand-text-tertiary font-mono px-2">
            Showing {filteredStocks.length} results
            {getSectorDisplayText()}
          </p>
      </div>

      <div className="overflow-x-auto">
        <table className="w-full text-sm text-left">
          <thead className="border-b border-brand-border">
            <tr>
              <th className="px-4 py-2 font-semibold text-brand-text-secondary">Symbol</th>
              <th className="px-4 py-2 font-semibold text-brand-text-secondary">Company</th>
              <th className="px-4 py-2 font-semibold text-brand-text-secondary">Sector</th>
              <th className="px-4 py-2 font-semibold text-brand-text-secondary text-right">Price</th>
              <th className="px-4 py-2 font-semibold text-brand-text-secondary text-right">Change %</th>
              <th className="px-4 py-2 font-semibold text-brand-text-secondary text-right">Market Cap</th>
              <th className="px-4 py-2 font-semibold text-brand-text-secondary text-right">P/E Ratio</th>
            </tr>
          </thead>
          <tbody>
            {filteredStocks.length > 0 ? (
              filteredStocks.map(stock => (
                <tr key={stock.id} className="border-b border-brand-border last:border-b-0 hover:bg-white/5 transition-colors">
                  <td className="px-4 py-3 font-mono font-medium text-brand-text-primary">{stock.symbol}</td>
                  <td className="px-4 py-3 text-brand-text-secondary truncate max-w-xs">{stock.companyName}</td>
                  <td className="px-4 py-3 text-brand-text-secondary">{stock.sector}</td>
                  <td className="px-4 py-3 font-mono text-right text-brand-text-primary">${stock.price.toFixed(2)}</td>
                  <td className={`px-4 py-3 font-mono text-right ${stock.changePercent >= 0 ? 'text-green-400' : 'text-red-400'}`}>
                    {stock.changePercent >= 0 ? '+' : ''}{stock.changePercent.toFixed(2)}%
                  </td>
                  <td className="px-4 py-3 font-mono text-right text-brand-text-secondary">{stock.marketCap}</td>
                  <td className="px-4 py-3 font-mono text-right text-brand-text-secondary">{stock.peRatio ? stock.peRatio.toFixed(2) : 'N/A'}</td>
                </tr>
              ))
            ) : (
              <tr>
                <td colSpan={7} className="text-center py-8 text-brand-text-secondary">
                  No stocks match the intersection of all selected screens{selectedSectors.includes('All') ? '' : ' in the selected sectors'}.
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
};

export default ScreenResults;
